import{_ as e,o as t,c as s,a2 as a}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E5%9C%BA%E6%99%AF%E8%81%94%E5%8A%A8%E5%88%97%E8%A1%A8.DnjB3TBP.png",o="/newx-doc/assets/%E5%88%9B%E5%BB%BA%E5%9C%BA%E6%99%AF%E8%81%94%E5%8A%A8.Cc2qO3AW.png",d="/newx-doc/assets/%E8%AE%BE%E5%A4%87%E8%A7%A6%E5%8F%91%E5%99%A8%E9%85%8D%E7%BD%AE.CccjIuAG.png",l="/newx-doc/assets/%E5%AE%9A%E6%97%B6%E8%A7%A6%E5%8F%91%E5%99%A8%E9%85%8D%E7%BD%AE.D38t1b-J.png",r="/newx-doc/assets/%E6%89%A7%E8%A1%8C%E5%8A%A8%E4%BD%9C%E9%85%8D%E7%BD%AE.DgSloyk0.png",h="/newx-doc/assets/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8B%E7%A4%BA%E4%BE%8B.CoIxKN-j.png",p="/newx-doc/assets/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8B-%E6%A8%A1%E6%8B%9F%E8%AE%BE%E5%A4%87.D9mkAetp.png",c="/newx-doc/assets/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8B-%E8%AE%BE%E5%A4%87%E6%B6%88%E6%81%AF.BdQphgvS.png",b=JSON.parse('{"title":"场景联动","description":"","frontmatter":{},"headers":[],"relativePath":"iot/scene-rule.md","filePath":"iot/scene-rule.md","lastUpdated":null}'),k={name:"iot/scene-rule.md"};function E(g,i,u,A,F,y){return t(),s("div",null,[...i[0]||(i[0]=[a('<h1 id="场景联动" tabindex="-1">场景联动 <a class="header-anchor" href="#场景联动" aria-label="Permalink to &quot;场景联动&quot;">​</a></h1><p>推荐阅读：</p><ul><li><a href="https://help.aliyun.com/zh/iot/user-guide/scene-orchestration-1" target="_blank" rel="noreferrer">《阿里云物联网平台 —— 什么是场景联动》</a></li><li><a href="https://help.aliyun.com/zh/iot/user-guide/scene-orchestrations-in-the-cloud" target="_blank" rel="noreferrer">《阿里云物联网平台 —— 云端场景联动》</a></li></ul><p>场景联动模块，由 <code>yudao-module-iot</code> 后端模块的 <code>rule/scene</code> 包实现。它使用&quot;触发器 + 执行条件 + 执行动作&quot;（TCA）模型，实现设备间的自动化联动。例如：</p><ul><li>温度传感器检测到温度超过 30°C 时，自动打开空调</li><li>每天早上 8 点定时检查所有设备是否在线，离线则触发告警</li></ul><h2 id="_1-场景联动规则" tabindex="-1">1. 场景联动规则 <a class="header-anchor" href="#_1-场景联动规则" aria-label="Permalink to &quot;1. 场景联动规则&quot;">​</a></h2><p>场景联动规则，由 IotSceneRuleController 提供接口。每个规则包含触发器配置和动作配置，规则匹配后自动执行动作。</p><h3 id="_1-1-表结构" tabindex="-1">1.1 表结构 <a class="header-anchor" href="#_1-1-表结构" aria-label="Permalink to &quot;1.1 表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iot_scene_rule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;场景联动编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `name`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;场景联动名称&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `description`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;场景联动描述&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;场景联动状态&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `last_trigger_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;最后触发时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `triggers`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;触发器配置（JSON 格式）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `actions`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;动作配置（JSON 格式）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BTREE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CHARSET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">utf8mb4 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COLLATE=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">utf8mb4_unicode_ci COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;IoT 场景联动规则表&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>name</code>、<code>description</code>：规则的基本信息，用于展示。</p><p>② <code>status</code>：规则状态，参见 CommonStatusEnum 枚举。开启后，规则才会生效。</p><p>③ <code>last_trigger_time</code>：最后触发时间，每次规则匹配成功并执行动作后更新。</p><p>④ <code>triggers</code>：触发器配置，JSON 格式存储。详见「1.1.1 触发器（Trigger）」小节。</p><p>⑤ <code>actions</code>：动作配置，JSON 格式存储。详见「1.1.2 动作（Action）」小节。</p><p>提示：</p><p>下面的 <code>triggers</code>、<code>actions</code> JSON 内嵌结构比较复杂，建议结合「1.3 管理后台（创建/编辑）」的界面截图一起看，会更容易理解。</p><h4 id="_1-1-1-触发器-trigger" tabindex="-1">1.1.1 触发器（Trigger） <a class="header-anchor" href="#_1-1-1-触发器-trigger" aria-label="Permalink to &quot;1.1.1 触发器（Trigger）&quot;">​</a></h4><p>① <code>triggers</code> 字段类型为 <code>List&lt;Trigger&gt;</code>，每个 Trigger 的核心字段如下：</p><ul><li><p><code>type</code>：触发类型，参见 IotSceneRuleTriggerTypeEnum 枚举。匹配流程由 IotSceneRuleMatcherManager 统一管理，具体见「2. 实现原理」小节。</p><table tabindex="0"><thead><tr><th>触发类型</th><th>说明</th><th>对应 Matcher 实现类</th></tr></thead><tbody><tr><td>设备上下线变更</td><td>设备上线或离线时触发</td><td>IotDeviceStateUpdateTriggerMatcher</td></tr><tr><td>物模型属性上报</td><td>设备上报属性数据时触发</td><td>IotDevicePropertyPostTriggerMatcher</td></tr><tr><td>设备事件上报</td><td>设备上报事件时触发</td><td>IotDeviceEventPostTriggerMatcher</td></tr><tr><td>设备服务调用</td><td>设备被调用服务时触发</td><td>IotDeviceServiceInvokeTriggerMatcher</td></tr><tr><td>定时触发</td><td>按 CRON 表达式定时触发</td><td>IotTimerTriggerMatcher</td></tr></tbody></table></li><li><p><code>productId</code>、<code>deviceId</code>：指定触发的产品和设备。<code>deviceId</code> 为 <code>-1</code> 时表示该产品下的全部设备</p></li><li><p><code>identifier</code>、<code>operator</code>、<code>value</code>：触发条件的具体判断（物模型标识符 + 操作符 + 值）</p></li><li><p><code>cronExpression</code>：CRON 表达式，仅「定时触发器」使用</p></li><li><p><code>conditionGroups</code>：执行条件组，类型为 <code>List&lt;List&lt;TriggerCondition&gt;&gt;</code>。二维数组结构：外层 OR、内层 AND</p><blockquote><p>条件组采用&quot;分组或、组内且&quot;的逻辑，即：分组之间是&quot;或&quot;的关系，同一分组内的条件是&quot;且&quot;的关系。例如 <code>(条件A 且 条件B) 或 (条件C)</code> 就是两个分组。</p></blockquote></li></ul><hr><p>② 每个 TriggerCondition 包含：</p><ul><li><p><code>type</code>：条件类型，参见 IotSceneRuleConditionTypeEnum 枚举：</p><table tabindex="0"><thead><tr><th>条件类型</th><th>说明</th><th>对应 Condition Matcher 实现类</th></tr></thead><tbody><tr><td>设备状态</td><td>判断设备在线/离线状态</td><td>IotDeviceStateConditionMatcher</td></tr><tr><td>设备属性</td><td>判断设备属性值</td><td>IotDevicePropertyConditionMatcher</td></tr><tr><td>当前时间</td><td>判断当前时间范围</td><td>IotCurrentTimeConditionMatcher</td></tr></tbody></table></li><li><p><code>productId</code>、<code>deviceId</code>、<code>identifier</code>、<code>operator</code>、<code>param</code>：具体的条件判断参数</p></li></ul><h4 id="_1-1-2-动作-action" tabindex="-1">1.1.2 动作（Action） <a class="header-anchor" href="#_1-1-2-动作-action" aria-label="Permalink to &quot;1.1.2 动作（Action）&quot;">​</a></h4><p><code>actions</code> 字段类型为 <code>List&lt;Action&gt;</code>，每个 Action 的核心字段如下：</p><ul><li><p><code>type</code>：动作类型，参见 IotSceneRuleActionTypeEnum 枚举：</p><table tabindex="0"><thead><tr><th>动作类型</th><th>说明</th><th>对应 Action 实现类</th></tr></thead><tbody><tr><td>设备属性设置</td><td>设置目标设备的属性值</td><td>IotDevicePropertySetSceneRuleAction</td></tr><tr><td>设备服务调用</td><td>调用目标设备的服务</td><td>IotDeviceServiceInvokeSceneRuleAction</td></tr><tr><td>告警触发</td><td>创建告警记录</td><td>IotAlertTriggerSceneRuleAction</td></tr><tr><td>告警恢复</td><td>批量处理未处理的告警记录</td><td>IotAlertRecoverSceneRuleAction</td></tr></tbody></table></li><li><p><code>productId</code>、<code>deviceId</code>、<code>identifier</code>、<code>params</code>：设备控制相关参数</p></li><li><p><code>alertConfigId</code>：告警配置编号，用于告警触发/恢复动作。关于告警触发和告警恢复，详见 <a href="./alert-config">《告警配置》</a>。</p></li></ul><h3 id="_1-2-管理后台-列表" tabindex="-1">1.2 管理后台（列表） <a class="header-anchor" href="#_1-2-管理后台-列表" aria-label="Permalink to &quot;1.2 管理后台（列表）&quot;">​</a></h3><p>对应 [IoT 物联网 -&gt; 规则引擎 -&gt; 场景联动] 菜单，对应前端项目的 <code>@/views/iot/rule/scene</code> 目录。</p><p><img src="'+n+'" alt="管理后台 - 场景联动列表"></p><h3 id="_1-3-管理后台-创建-编辑" tabindex="-1">1.3 管理后台（创建/编辑） <a class="header-anchor" href="#_1-3-管理后台-创建-编辑" aria-label="Permalink to &quot;1.3 管理后台（创建/编辑）&quot;">​</a></h3><p>点击【新增】按钮，右侧弹出抽屉表单。表单分为三个区域：基础信息、触发器配置、执行动作配置。</p><p><img src="'+o+'" alt="管理后台 - 创建场景联动"></p><h4 id="_1-3-1-基础信息" tabindex="-1">1.3.1 基础信息 <a class="header-anchor" href="#_1-3-1-基础信息" aria-label="Permalink to &quot;1.3.1 基础信息&quot;">​</a></h4><p>包括规则名称、规则描述、规则状态。</p><h4 id="_1-3-2-触发器配置" tabindex="-1">1.3.2 触发器配置 <a class="header-anchor" href="#_1-3-2-触发器配置" aria-label="Permalink to &quot;1.3.2 触发器配置&quot;">​</a></h4><p>支持添加多个触发器，每个触发器需要选择触发类型，再根据类型配置具体参数：</p><p>① <strong>设备触发</strong>（属性上报/事件上报/服务调用/状态变更）：选择产品 → 设备（支持全部设备）→ 物模型标识符 → 操作符 → 值。</p><p>还可以添加执行条件组，条件组支持&quot;设备状态&quot;、&quot;设备属性&quot;、&quot;当前时间&quot;三种类型。</p><p><img src="'+d+'" alt="管理后台 - 设备触发器配置"></p><hr><p>② <strong>定时触发</strong>：输入 CRON 表达式，同样可以添加执行条件组。</p><p><img src="'+l+'" alt="管理后台 - 定时触发器配置"></p><h4 id="_1-3-3-执行动作配置" tabindex="-1">1.3.3 执行动作配置 <a class="header-anchor" href="#_1-3-3-执行动作配置" aria-label="Permalink to &quot;1.3.3 执行动作配置&quot;">​</a></h4><p>支持添加多个执行动作，每个动作需要选择动作类型：</p><ul><li>设备属性设置：选择产品 → 设备 → 属性 → 设置值</li><li>设备服务调用：选择产品 → 设备 → 服务 → 调用参数</li><li>告警触发 / 告警恢复：选择关联的告警配置</li></ul><p><img src="'+r+'" alt="管理后台 - 执行动作配置"></p><h2 id="_2-快速上手" tabindex="-1">2. 快速上手 <a class="header-anchor" href="#_2-快速上手" aria-label="Permalink to &quot;2. 快速上手&quot;">​</a></h2><p>以内置的 id 为 25 的 <a href="http://127.0.0.1/iot/device/detail/25" target="_blank" rel="noreferrer">演示设备</a> 为例，演示如何配置一条场景联动规则：当设备上报的 <code>width</code> 属性大于 1000 时，自动触发服务调用。</p><h3 id="_2-1-步骤一-创建场景联动规则" tabindex="-1">2.1 步骤一：创建场景联动规则 <a class="header-anchor" href="#_2-1-步骤一-创建场景联动规则" aria-label="Permalink to &quot;2.1 步骤一：创建场景联动规则&quot;">​</a></h3><p>进入 [IoT 物联网 -&gt; 规则引擎 -&gt; 场景联动]，点击【新增】按钮创建一条规则，配置如下：</p><blockquote><p>系统已预设了一条名为&quot;宽度超标触发服务调用&quot;的演示规则，可直接用于体验，跳过本步骤。</p></blockquote><p><img src="'+h+'" alt="快速上手 - 配置示例"></p><ul><li>触发器：物模型属性上报 → 演示产品 → 全部设备 → <code>width</code> &gt; <code>1000</code></li><li>执行动作：设备服务调用 → 演示产品 → 演示设备</li></ul><h3 id="_2-2-步骤二-测试验证" tabindex="-1">2.2 步骤二：测试验证 <a class="header-anchor" href="#_2-2-步骤二-测试验证" aria-label="Permalink to &quot;2.2 步骤二：测试验证&quot;">​</a></h3><blockquote><p>【可选】如需调试，可在 IotDeviceServiceInvokeSceneRuleAction 的 <code>#execute(...)</code> 方法打断点，验证服务调用动作是否被执行。</p></blockquote><p>① 使用设备管理的&quot;模拟设备&quot;功能，模拟演示设备上报 <code>width</code> 属性值为 <code>1500</code>（大于 1000）。</p><p><img src="'+p+'" alt="快速上手 - 模拟设备上报属性"></p><p>② 在设备详情的「设备消息」Tab，可以看到触发了一条&quot;服务调用&quot;的下行消息，说明场景联动执行成功。</p><p><img src="'+c+`" alt="快速上手 - 设备消息"></p><h2 id="_3-实现原理" tabindex="-1">3. 实现原理 <a class="header-anchor" href="#_3-实现原理" aria-label="Permalink to &quot;3. 实现原理&quot;">​</a></h2><p>简要介绍场景联动的后端架构，帮助二次开发的同学理解核心流程。</p><h3 id="_3-1-整体架构" tabindex="-1">3.1 整体架构 <a class="header-anchor" href="#_3-1-整体架构" aria-label="Permalink to &quot;3.1 整体架构&quot;">​</a></h3><p>场景联动采用&quot;消息订阅 + 匹配器 + 执行器&quot;三层架构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备消息 → IotSceneRuleMessageSubscriber（消息订阅）</span></span>
<span class="line"><span>       → IotSceneRuleMatcherManager（匹配器管理）</span></span>
<span class="line"><span>       → IotSceneRuleAction（动作执行）</span></span></code></pre></div><h3 id="_3-2-消息订阅" tabindex="-1">3.2 消息订阅 <a class="header-anchor" href="#_3-2-消息订阅" aria-label="Permalink to &quot;3.2 消息订阅&quot;">​</a></h3><p>IotSceneRuleMessageSubscriber 订阅设备消息 Topic <code>iot_device_message</code>，收到消息后调用 IotSceneRuleService 的 <code>#executeSceneRuleByDevice(...)</code> 方法。</p><h3 id="_3-3-触发器匹配" tabindex="-1">3.3 触发器匹配 <a class="header-anchor" href="#_3-3-触发器匹配" aria-label="Permalink to &quot;3.3 触发器匹配&quot;">​</a></h3><p>使用策略模式，每种触发类型对应一个 Matcher 实现类（实现 IotSceneRuleTriggerMatcher 接口），具体对应关系见「1.1.1 触发器（Trigger）」小节中的表格。</p><p>条件匹配使用 Spring Expression（SpEL）进行表达式评估，操作符定义在 IotSceneRuleConditionOperatorEnum 枚举中，支持 <code>=</code>、<code>!=</code>、<code>&gt;</code>、<code>&gt;=</code>、<code>&lt;</code>、<code>&lt;=</code>、<code>in</code>、<code>not in</code>、<code>between</code>、<code>like</code>、时间比较等。</p><h3 id="_3-4-定时触发" tabindex="-1">3.4 定时触发 <a class="header-anchor" href="#_3-4-定时触发" aria-label="Permalink to &quot;3.4 定时触发&quot;">​</a></h3><p>定时触发基于 Quartz 实现。IotSceneRuleTimerHandler 管理定时任务的注册、更新、暂停和注销。规则启用时自动注册 Quartz 定时任务，禁用时自动暂停。</p><p>定时触发与设备触发的区别：定时触发没有设备消息上下文，条件评估时需要通过 IotTimerConditionEvaluator 主动查询设备的最新属性值或状态。</p><h3 id="_3-5-动作执行" tabindex="-1">3.5 动作执行 <a class="header-anchor" href="#_3-5-动作执行" aria-label="Permalink to &quot;3.5 动作执行&quot;">​</a></h3><p>同样使用策略模式，每种动作类型对应一个 Action 实现类（实现 IotSceneRuleAction 接口），具体对应关系见「1.1.2 动作（Action）」小节中的表格。</p>`,74)])])}const m=e(k,[["render",E]]);export{b as __pageData,m as default};
